// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address admin;

    function setUp() public {
        c = new Owned();
        admin = msg.sender;
    }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != admin);
        bool ok;
        vm.prank(actor);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok && c.owner() != newOwner);
    }
}
